// Embedded offline artwork and animation. No network requests.
export const MOVO_HTML: string = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><title>MOVO</title></head><body>\n<div id=\"movo-signature\" aria-label=\"MOVO signature animation\">\n <div class=\"movo-stage\"><div class=\"movo-screen\"><canvas width=\"1170\" height=\"2340\" role=\"img\" aria-label=\"MOVO draws in flowing white strokes, its smiling green face settles into place\"></canvas></div></div>\n</div>\n<style>\nhtml,body{margin:0;width:100%;height:100%;background:#043345;overflow:hidden}\n#movo-signature,.movo-stage{width:100%;height:100%}\n.movo-stage{display:flex;align-items:center;justify-content:center}\n.movo-screen{width:min(100vw,50vh);width:min(100vw,50dvh);aspect-ratio:1/2;background:#043345}\ncanvas{display:block;width:100%;height:100%}\n</style>\n<script>\n(()=>{\nconst root=document.getElementById('movo-signature'),canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d');\nconst reduced=matchMedia('(prefers-reduced-motion: reduce)');\nconst settings={speed:1,loop:false};\nconst image=new Image();let body,word,ready=false,elapsed=0,last=0,raf=0,notified=false;\nfunction notify(message){window.ReactNativeWebView?.postMessage(message)}\nconst clamp=n=>Math.max(0,Math.min(1,n));\nconst smooth=n=>{n=clamp(n);return n*n*(3-2*n)};\n// Each path is measured once. Reveals advance by distance, not segment count.\nfunction path(commands){let pts=[],p=[0,0];for(const cmd of commands){const [op,...a]=cmd;if(op==='M'){p=a;pts.push({x:p[0],y:p[1],move:true})}else if(op==='L'){p=a;pts.push({x:p[0],y:p[1]})}else if(op==='C'){const s=p;for(let k=1;k<=32;k++){const t=k/32,u=1-t;pts.push({x:u*u*u*s[0]+3*u*u*t*a[0]+3*u*t*t*a[2]+t*t*t*a[4],y:u*u*u*s[1]+3*u*u*t*a[1]+3*u*t*t*a[3]+t*t*t*a[5]})}p=[a[4],a[5]]}}\n let length=0;for(let i=0;i<pts.length;i++){if(i&&!pts[i].move)length+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);pts[i].distance=length}return {pts,length};}\nfunction stroke(c,p,progress,width,color){if(progress<=0)return;const limit=p.length*clamp(progress);c.beginPath();for(let i=0;i<p.pts.length;i++){const v=p.pts[i];if(v.distance<=limit){if(v.move)c.moveTo(v.x,v.y);else c.lineTo(v.x,v.y)}else{const a=p.pts[i-1];if(a&&!v.move){const f=(limit-a.distance)/(v.distance-a.distance);c.lineTo(a.x+(v.x-a.x)*f,a.y+(v.y-a.y)*f)}break}}c.lineWidth=width;c.lineCap='round';c.lineJoin='round';c.strokeStyle=color;c.stroke()}\nconst mark=path([['M',58,257],['C',73,203,88,139,103,88],['C',114,42,137,40,163,75],['C',211,131,237,180,275,181],['C',310,181,343,124,386,76],['C',410,39,436,41,447,91],['C',465,155,480,212,492,257]]);\nconst letters=[\n path([['M',22,109],['L',37,25],['L',78,86],['L',123,25],['L',138,109]]),\n path([['M',226,20],['C',160,20,158,112,226,112],['C',294,112,292,20,226,20]]),\n path([['M',309,23],['L',356,112],['L',401,23]]),\n path([['M',483,20],['C',417,20,415,112,483,112],['C',551,112,549,20,483,20]])\n];\nfunction cut(x,y,w,h){const c=document.createElement('canvas');c.width=w;c.height=h;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(image,x,y,w,h,0,0,w,h);const d=cx.getImageData(0,0,w,h);for(let i=0;i<d.data.length;i+=4){const a=clamp((d.data[i]-25)/220);d.data[i]=255;d.data[i+1]=255;d.data[i+2]=255;d.data[i+3]=Math.round(a*255)}cx.putImageData(d,0,0);return c}\nconst layer=document.createElement('canvas');layer.width=555;layer.height=315;const lc=layer.getContext('2d');\nfunction reveal(texture,paths,amounts,widths,x,y){lc.clearRect(0,0,555,315);lc.globalCompositeOperation='source-over';paths.forEach((p,i)=>stroke(lc,p,amounts[i],widths[i],'#fff'));lc.globalCompositeOperation='source-in';lc.drawImage(texture,0,0);lc.globalCompositeOperation='source-over';ctx.drawImage(layer,x,y)}\nfunction render(seconds){ctx.setTransform(3,0,0,3,0,0);ctx.clearRect(0,0,390,780);if(!ready)return;const t=reduced.matches?5:seconds;\n ctx.save();ctx.translate(195,412);ctx.scale(.38,.38);\n // The M draws in one continuous gesture; its original silhouette is retained.\n reveal(body,[mark],[smooth((t-.12)/1.25)],[145],-275,-305);\n // The green face arrives after the first crest, with a restrained settle.\n const dot=smooth((t-.83)/.49);if(dot>0){const settle=Math.sin(clamp((t-1.15)/.5)*Math.PI)*2.2;ctx.save();ctx.translate(0,-355-settle);ctx.scale(dot,dot);if(head.complete&&head.naturalWidth)ctx.drawImage(head,-90,-90,180,180);ctx.restore()}\n // Every letter is written along its own stroke, never wiped across a box.\n const starts=[1.12,1.36,1.58,1.78],durations=[.57,.6,.5,.62];\n reveal(word,letters,starts.map((s,i)=>smooth((t-s)/durations[i])),[42,43,42,43],-277.5,20);\n ctx.restore();\n}\nfunction frame(ms){if(last&&document.visibilityState!=='hidden')elapsed+=Math.min(.05,(ms-last)/1000)*settings.speed;last=ms;if(settings.loop&&elapsed>6.5)elapsed=0;render(elapsed);if(!notified&&ready&&(elapsed>=2.8||reduced.matches)){notified=true;notify('movo:complete')}if(!reduced.matches||elapsed<4.1||settings.loop){raf=requestAnimationFrame(frame)}else{raf=0;last=0}}\nfunction play(){elapsed=0;last=0;if(raf)cancelAnimationFrame(raf);raf=requestAnimationFrame(frame)}\n\n// The head is the app's happy mood icon (assets/moods/happy.png), embedded so the page stays offline.\nconst head=new Image();head.src='data:image/png;base64,';\nimage.onload=()=>{body=cut(370,665,550,315);word=cut(365,990,555,135);ready=true;render(0);notify('movo:ready');play()};image.src='data:image/jpeg;base64,';\nreduced.addEventListener('change',()=>render(elapsed));\n// Deterministic frame access for layout and animation review.\nwindow.movo={replay:play,seek:t=>{if(raf)cancelAnimationFrame(raf);raf=0;elapsed=t;render(t)},isReady:()=>ready};\n})();\n</script>\n\n</body></html>";
